<template>
  <div class="generated-images-page hidden-scrollbar">
    <!-- 页面标题 -->
    <div class="page-header" v-if="showTitle">
      <h1 class="page-title">{{ t('picturesGenerated') }}</h1>
    </div>

    <!-- 错误状态 -->
    <div v-if="errorMessage" class="error-container">
      <div class="error-text">{{ errorMessage }}</div>
      <l-button class="retry-btn" @click="loadImages" :text="t('retry')" ></l-button>
    </div>

    <!-- 空数据状态 -->
    <div v-else-if="imageList.length === 0 && !isLoading" class="empty-container">
      <l-img src="/static/images/image_placeholder_icon.png" w="80px" h="auto" fit="cover" />
      <p class="empty-text">{{ dataSource === 'favorites' ? t('favorites.empty') : t('history.empty') }}</p>
    </div>

    <!-- 图片网格容器 -->
    <div v-if="imageList.length" class="images-grid-container">
      <div class="images-grid">
        <!-- 图片卡片列表 -->
        <div 
          v-for="image in imageList" 
          :key="image.id"
          class="image-card"
          @click="handleImageClick(image)"
        >
          <!-- 图片显示区域 -->
          <div class="image-area">
              <l-img 
                :src="image.imageUrl" 
                w="100%" 
                h="100%" 
                fit="cover"
                class="card-image"
                show-error-type="image"
                @error="handleImageError"
              />
          </div>
          
          <!-- 图片描述信息 -->
          <div class="image-info">
            <p class="image-description">{{ image.description }}</p>
            <div class="image-footer">
              <p class="image-date">{{ image.createdDate }}</p>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- 分页组件 -->
    <div v-if="!isLoading && !errorMessage && imageList.length > 0" class="pagination-container">
      <Pagination
        :current-page="currentPage"
        :page-size="pageSize"
        :total="totalCount"
        :page-sizes="[20,30,40,50]"
        :show-page-sizes="true"
        :show-jumper="true"
        @current-change="handleCurrentChange"
        @size-change="handleSizeChange"
      />
    </div>

    <!-- 图片详情弹框 -->
    <ImageDetailDialog
      v-model="showDetailDialog"
      :image-list="imageList"
      :current-index="currentImageIndex"
      @update:current-index="currentImageIndex = $event"
    />

    <!-- 统一图片详情弹框 - 增强模式 -->
    <ImageDetailDialogUnified
      v-model="showEnhanceDialog"
      :image-data="currentEnhanceImage"
      mode="enhance"
    />

    <!-- 统一图片详情弹框 - 放大模式 -->
    <ImageDetailDialogUnified
      v-model="showZoomDialog"
      :image-data="currentZoomImage"
      mode="zoom"
    />

    <!-- 统一图片详情弹框 - 编辑模式 -->
    <ImageDetailDialogUnified
      v-model="showEditDialog"
      :image-data="currentEditImage"
      mode="edit"
    />
  </div>
</template>

<script setup>
import { ref, onMounted, computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import Pagination from '@/components/pagination.vue';
import ImageDetailDialog from '@/components/produce-media/images-detail-dialog.vue';
import ImageDetailDialogUnified from '@/components/produce-media/media-detail-dialog.vue';
import { ApiGeneration } from '@/api/api-generation';
import { fullScreenLoading } from '@/utils/ui-feedback';
import LButton from '@/components/l-button.vue';

// Props
const props = defineProps({
  showTitle: {
    type: Boolean,
    default: true
  },
  dataSource: {
    type: String,
    default: 'history', // 'history' | 'favorites'
    validator: (value) => ['history', 'favorites'].includes(value)
  }
});

// 多语言支持
const { t } = useI18n();

// 响应式数据
const currentPage = ref(1);
const pageSize = ref(20); // 固定20条
const totalCount = ref(0);
const imageList = ref([]);

// 详情弹框相关
const showDetailDialog = ref(false);
const currentImageIndex = ref(0);

// 增强弹框相关
const showEnhanceDialog = ref(false);
const currentEnhanceImage = ref(null);

// 放大弹框相关
const showZoomDialog = ref(false);
const currentZoomImage = ref(null);

// 编辑弹框相关
const showEditDialog = ref(false);
const currentEditImage = ref(null);

// 状态管理
const isLoading = ref(false);
const errorMessage = ref('');

// 监听事件区域
const handleImageClick = (image) => {
  // 打开详情弹框
  const index = imageList.value.findIndex(item => item.id === image.id);
  console.log('Found image index:', index);
  console.log('Total images in list:', imageList.value.length);
  
  if (index !== -1) {
    currentImageIndex.value = index;
    showDetailDialog.value = true;
    console.log('Opening dialog with index:', index);
  } else {
    console.error('Image not found in list:', image.id);
  }
};

const handleImageError = (error) => {
  console.warn('Image load error:', error);
  console.warn('Error target:', error.target);
  if (error.target) {
    console.warn('Failed image src:', error.target.src);
  }
  // 可以设置默认图片或错误处理
};

const handleEnhanceClick = (image) => {
  console.log('Enhance image clicked:', image);
  // 打开增强弹框
  currentEnhanceImage.value = image;
  showEnhanceDialog.value = true;
};

const handleZoomClick = (image) => {
  console.log('Zoom image clicked:', image);
  // 打开放大弹框
  currentZoomImage.value = image;
  showZoomDialog.value = true;
};

const handleEditClick = (image) => {
  // 打开编辑弹框
  currentEditImage.value = image;
  showEditDialog.value = true;
};

const handleSizeChange = (newSize) => {
  pageSize.value = newSize;
  currentPage.value = 1;
  loadImages();
};

const handleCurrentChange = (newPage) => {
  currentPage.value = newPage;
  loadImages();
};

// 业务逻辑区域
const loadImages = async () => {
  const loading = fullScreenLoading();
  try {
    isLoading.value = true;  
    errorMessage.value = '';
    
    // 构建请求参数
    const params = {
      media_type: 'image',
      page: currentPage.value,
      page_size: pageSize.value
    };


    // 根据数据源调用不同的API
    const response = props.dataSource === 'favorites' 
      ? await ApiGeneration.getFavorites(params)
      : await ApiGeneration.getHistory(params);


    // 检查响应状态
    if (response.code !== 200) {
      throw new Error(response.message || 'Failed to load images');
    }

    // 转换分页数据
        const paginationData = ApiGeneration.transformPaginationData(response);

    // 转换图片数据
    const transformedImages = ApiGeneration.transformToImageData(paginationData.items);
    
    // 更新状态
    imageList.value = transformedImages;
    totalCount.value = paginationData.total;
    currentPage.value = paginationData.currentPage;
    pageSize.value = paginationData.pageSize;

    loading.close();
    isLoading.value = false;
  } catch (error) {
    console.error('Failed to load image list:', error);
    errorMessage.value = props.dataSource === 'favorites' 
      ? t('favorites.error') 
      : t('history.error');
    
    // 设置空数据
    imageList.value = [];
    totalCount.value = 0;
  } finally {
    loading.close();
    isLoading.value = false;
  }
};

// 监听props变化
watch(() => props.dataSource, () => {
  // 数据源变化时重置分页并重新加载
  currentPage.value = 1;
  loadImages();
}, { immediate: false });

// 周期函数区域
onMounted(() => {
  loadImages();
});
</script>

