<template>
  <CommonDialog
    v-model="dialogVisible"
    :close-on-click-modal="true"
    :close-on-press-escape="true"
    @close="handleClose"
    :isScale="false"
  >
    <div class="image-detail-dialog">
      <!-- 左侧图片区域 -->
      <div class="image-section">
        <!-- 图片容器 -->
        <div class="image-container" :style="{backgroundColor: imageLoadError ? 'transparent' : 'black'}">
          <div class="image-wrapper">
            <l-img 
              :src="currentImage?.imageUrl || ''" 
              w="100%" 
              h="100%" 
              fit="contain"
              class="detail-image"
              :show-error-type="'image'"
              @onError="handleImageError"
            />
          </div>
        </div>
      </div>

      <!-- 右侧详情区域 -->
      <div class="details-section">
        <!-- 标题 -->
        <h2 class="detail-title">{{ t('generateImage') }}</h2>
        <p class="detail-subtitle">{{ t('selectStyleToGenerate') }}</p>

        <!-- Prompt 区域 -->
        <div class="field-group">
          <label class="field-label">{{ t('prompt') }}</label>
          <p class="field-placeholder">{{ t('enterPromptToGenerate') }}</p>
          <div class="textarea-container">
            <div class="textarea-content" :title="currentImage?.prompt">
              {{ currentImage?.prompt}}
            </div>
            <button 
              class="copy-btn"
              @click="handleCopy"
              :aria-label="t('copy')"
            >
              <l-img 
                :src="'/static/images/copy_icon.png'" 
                w="24px" 
                h="24px"
                class="copy-icon"
              />
              <span class="copy-text">{{ t('copy') }}</span>
            </button>
          </div>
        </div>

        <!-- Model 区域 -->
        <div class="field-group">
          <label class="field-label">{{ t('model') }}</label>
          <div class="field-value model-value">
            {{ currentImage?.model || 'Unknown Model' }}
          </div>
        </div>

        <!-- Resolution 区域 -->
        <div class="field-group">
          <label class="field-label">{{ t('resolution') }}</label>
          <div class="field-value resolution-value">
            {{ currentImage?.resolution || 'HD' }}
          </div>
        </div>

        <!-- Image Dimensions 区域 -->
        <div class="field-group">
          <label class="field-label">{{ t('imageDimensions') }}</label>
          <div class="dimensions-value">
            <AspectRatio :aspect-ratio="currentImage?.dimensions || '1:1'" />
            {{ currentImage?.dimensions || '1:1' }}
          </div>
        </div>

        <!-- Seed 区域 -->
        <div class="field-group" v-if="currentImage?.seed">
          <label class="field-label">{{ t('seedOptional') }}</label>
          <div class="field-value seed-value">
            {{ currentImage?.seed}}
          </div>
        </div>
      </div>
    </div>
  </CommonDialog>
</template>

<script setup>
import { ref, computed, watch, nextTick, onMounted, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';
import CommonDialog from '@/components/common-dialog.vue';
import LImg from '@/components/l-img.vue';
import AspectRatio from '@/components/aspectRatio.vue';
import { showMessageSuccess } from '@/utils/ui-feedback';
import { copy } from '@/utils/util.js';

// 多语言支持
const { t } = useI18n();

// Props
const props = defineProps({
  modelValue: {
    type: Boolean,
    default: false
  },
  imageList: {
    type: Array,
    default: () => []
  },
  currentIndex: {
    type: Number,
    default: 0
  }
});



// Emits
const emit = defineEmits(['update:modelValue', 'update:current-index']);

// 响应式数据
const dialogVisible = ref(props.modelValue);

// 图片加载错误
const imageLoadError = ref(false);

// 计算属性
const currentImage = computed(() => {
  return props.imageList[props.currentIndex] || null;
});

// 监听modelValue变化
watch(() => props.modelValue, (newVal) => {
  dialogVisible.value = newVal;
});

watch(dialogVisible, (newVal) => {
  emit('update:modelValue', newVal);
});

// 事件处理函数
const handleClose = () => {
  dialogVisible.value = false;
  imageLoadError.value = false;
};

const handlePrevious = () => {
  if (props.currentIndex > 0) {
    emit('update:current-index', props.currentIndex - 1);
  }
};

const handleNext = () => {
  if (props.currentIndex < props.imageList.length - 1) {
    emit('update:current-index', props.currentIndex + 1);
  }
};

const handleImageError = (error) => {
  console.log('-----handleImageError-----', error);
  imageLoadError.value = true;
};

const handleCopy = async () => {
  const textToCopy = currentImage.value?.prompt || '';

  if (!textToCopy.trim()) {
    console.warn(t('nothingToCopy'));
    return;
  }

  try {
    copy(textToCopy);
    showMessageSuccess(t('copySuccess'));
  } catch (error) {
    console.error(t('copyFailed'), error);
    // 可以选择是否显示错误消息
    // showMessageError(t('copyFailed'));
  }
};
</script>

